rea_field('متن معرفی اختصاصی صفحه','seo_intro',$productSeo['intro']);?></fieldset><label>آپلود عکس محصول<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" data-photo></label><small>عکس JPEG، PNG یا WebP تا ۵ مگابایت و ۱۲ مگاپیکسل. عکس هنگام ذخیره محصول بهینه و ذخیره می‌شود.</small><img data-preview src="<?=h($p['image']?:'/products/hero.svg')?>" width="160" height="160" alt="پیش‌نمایش تصویر" class="upload-preview"><?php field('مسیر تصویر فعلی (پس از انتخاب فایل لازم نیست تغییر دهید)','image',$p['image'],'text',false);?><fieldset class="feature-editor"><legend>ویژگی‌ها و آیکون‌ها</legend><p>برای هر ویژگی نام و مقدار را وارد کنید؛ ردیف خالی ذخیره نمی‌شود.</p><?php $features=$p['id']?product_features((int)$p['id']):[];for($i=0;$i<8;$i++):$f=$features[$i]??['name'=>'','value'=>'','icon'=>['dimensions','weight','material','size','thickness','color','count','other'][$i]];?><div class="feature-editor-row"><input name="feature_name[]" maxlength="80" value="<?=h($f['name'])?>" placeholder="مثلاً ابعاد"><input name="feature_value[]" maxlength="180" value="<?=h($f['value'])?>" placeholder="مثلاً ۳۰ × ۴۰ سانتی‌متر"><select name="feature_icon[]"><?php foreach(['dimensions'=>'ابعاد','weight'=>'وزن','material'=>'جنس','size'=>'اندازه','thickness'=>'ضخامت','color'=>'رنگ','count'=>'تعداد','other'=>'سایر']as$icon=>$label):?><option value="<?=$icon?>" <?=$f['icon']===$icon?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></div><?php endfor;?></fieldset><div class="buy-row"><button class="btn">ذخیره محصول</button><a class="btn outline" href="/admin?tab=products">انصراف</a></div></form><?php endif;?><div class="table-scroll"><table><thead><tr><th>محصول</th><th>قیمت خرده / عمده</th><th>موجودی</th><th>عملیات</th></tr></thead><tbody><?php foreach(all('SELECT * FROM ns_products WHERE active=1 ORDER BY id DESC LIMIT 500')as$p):?><tr><td><?=h($p['name'])?></td><td><?=money($p['retail'])?> / <?=money($p['wholesale'])?></td><td><?=money($p['stock'])?></td><td><a class="text-link" href="/admin?tab=products&edit=<?=$p['id']?>">ویرایش</a><?php action_start('delete_product','','/admin');hidden('id',$p['id']);?><button class="icon-button" data-confirm="محصول از فروشگاه حذف شود؟ سوابق سفارش باقی می‌مانند.">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php
}

